"""ClaimSource that reads claims pre-generated by scripts/generate_claims.py."""
import json
from pathlib import Path
from typing import Iterator, Optional

from common.datasets.base import LabeledClaim
from common.paths import claims_dir


class JsonlClaimSource:
    """Reads data/claims/<dataset>/<split>[_<tag>].jsonl. One JSON object per line:
    {"claim", "label", "gold_triple", ...extra metadata ignored by `claims()`}.
    `gold_triple` may be null (FactKG claims have no single gold triple).
    """

    def __init__(self, dataset: str):
        self.dataset = dataset

    def path(self, split: str, tag: Optional[str] = None) -> Path:
        """data/claims/<dataset>/<split>[_<tag>].jsonl (tag e.g. "hard" for frequency-weighted negatives)."""
        return claims_dir(self.dataset) / f"{split}{'_' + tag if tag else ''}.jsonl"

    def records(self, split: str, tag: Optional[str] = None) -> Iterator[dict]:
        """Raw JSON records, including metadata (`corrupted` side, `source_triple`) that LabeledClaim drops."""
        path = self.path(split, tag)
        if not path.exists():
            raise FileNotFoundError(f"{path} not found. Run scripts/generate_claims.py first.")
        with open(path, encoding="utf-8") as f:
            for line in f:
                if line.strip():
                    yield json.loads(line)

    def claims(self, split: str, tag: Optional[str] = None) -> Iterator[LabeledClaim]:
        for d in self.records(split, tag):
            gold = d.get("gold_triple")
            yield LabeledClaim(claim=d["claim"], label=d["label"],
                               gold_triple=(gold[0], gold[1], gold[2]) if gold else None)
